import{_ as e,o as r,c as f,a3 as o}from"./chunks/framework.CJlOecQn.js";const d=JSON.parse('{"title":"التأشيرات العائلية","description":"كيف يستقدم المقيم زوجته وأبناءه للإقامة في قطر، ويستضيف أقاربه في زيارة عائلية، ويُدخل مولوده الجديد.","frontmatter":{"title":"التأشيرات العائلية","description":"كيف يستقدم المقيم زوجته وأبناءه للإقامة في قطر، ويستضيف أقاربه في زيارة عائلية، ويُدخل مولوده الجديد.","lastChecked":"2026-10","sourceCount":7},"headers":[],"relativePath":"ar/guide/family-visas.md","filePath":"ar/guide/family-visas.md"}'),t={name:"ar/guide/family-visas.md"};function s(n,a,l,i,c,p){return r(),f("div",null,[...a[0]||(a[0]=[o('<h1 id="التأشيرات-العائلية" tabindex="-1">التأشيرات العائلية <a class="header-anchor" href="#التأشيرات-العائلية" aria-label="Permalink to &quot;التأشيرات العائلية&quot;">​</a></h1><p>إذا كنت تحمل رخصة إقامة سارية للعمل في قطر، يمكنك التقدم لاستقدام زوجتك وأبنائك للإقامة معك، أو استضافة أقاربك في زيارة عائلية. ويُقدَّم الطلبان عبر تطبيق مطراش2.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><p>عدّلت وزارة الداخلية هذه الضوابط في إعلان بتاريخ 05/12/2023، فأصبحت شروط الراتب والسكن مرتبطة بما ورد في عقد العمل الإلكتروني للموظف.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h2 id="الإقامة-العائلية-للزوجة-والأبناء" tabindex="-1">الإقامة العائلية للزوجة والأبناء <a class="header-anchor" href="#الإقامة-العائلية-للزوجة-والأبناء" aria-label="Permalink to &quot;الإقامة العائلية للزوجة والأبناء&quot;">​</a></h2><h3 id="من-يحق-له-التقدم" tabindex="-1">من يحق له التقدم <a class="header-anchor" href="#من-يحق-له-التقدم" aria-label="Permalink to &quot;من يحق له التقدم&quot;">​</a></h3><ul><li>يلزمك رخصة إقامة سارية للعمل.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></li><li>يُشترط لموظفي القطاع الحكومي وشبه الحكومي مهنة عليا موثقة بعقد العمل أو بخطاب رسمي من جهة العمل، إضافة إلى سكن عائلي من جهة العمل أو راتب شهري لا يقل عن 10,000 ريال قطري موثق بالعقد.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>يُشترط لموظفي القطاع الخاص مهنة فنية أو تخصصية (غير عمالية) موثقة بالعقد، وراتب لا يقل عن 10,000 ريال قطري، أو 6,000 ريال قطري مع سكن عائلي من جهة العمل موثق بالعقد.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>ما زالت صفحة شروط قديمة لدى الوزارة تذكر 7,000 ريال لخيار السكن، بينما يذكر إعلان 2023 وصفحة الخدمة مبلغ 6,000 ريال.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup><sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li></ul><h3 id="من-يمكنك-استقدامه" tabindex="-1">من يمكنك استقدامه <a class="header-anchor" href="#من-يمكنك-استقدامه" aria-label="Permalink to &quot;من يمكنك استقدامه&quot;">​</a></h3><ul><li>تشمل صفحة الخدمة الزوجات والأبناء القادمين لأول مرة بسمة إقامة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>يُشترط ألا يزيد سن الابن عن 25 سنة وأن تكون الابنة غير متزوجة.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li></ul><h3 id="ما-تحتاجه" tabindex="-1">ما تحتاجه <a class="header-anchor" href="#ما-تحتاجه" aria-label="Permalink to &quot;ما تحتاجه&quot;">​</a></h3><ul><li>صورة جواز سفر ساري للوافد المستضيف.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>مستند يثبت صلة القرابة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li><li>شهادة حسن السيرة والسلوك لأفراد العائلة من سن 18 سنة فأكثر.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>تأمين صحي يغطي مدة الإقامة ويسري من تاريخ دخول البلاد.<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3]</a></sup></li></ul><h3 id="الأبناء-في-سن-التعليم" tabindex="-1">الأبناء في سن التعليم <a class="header-anchor" href="#الأبناء-في-سن-التعليم" aria-label="Permalink to &quot;الأبناء في سن التعليم&quot;">​</a></h3><p>يجب تسجيل الأبناء في سن التعليم الإلزامي من 6 إلى 18 سنة في المدارس المرخصة داخل الدولة، أو إرفاق ما يفيد قيدهم بالتعليم خارج الدولة من خلال منصة التعليم التي تشرف عليها وزارة التربية والتعليم والتعليم العالي. وتذكر وزارة الداخلية أن هذا الشرط إلزامي عند منح رخصة الإقامة وعند تجديدها.<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3]</a></sup></p><h3 id="كيف-تقدم-الطلب" tabindex="-1">كيف تقدم الطلب <a class="header-anchor" href="#كيف-تقدم-الطلب" aria-label="Permalink to &quot;كيف تقدم الطلب&quot;">​</a></h3><ol><li>قدّم الطلب عبر مطراش2 وارفع المستندات.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li><li>بعد وصول عائلتك بسمة إقامة، يجرون الفحص الطبي خلال ثلاثين يومًا، ثم البصمة وإجراءات الإقامة.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li></ol><p>الخطوات التالية مشروحة في صفحة <a href="./residence-permit-and-qid">رخصة الإقامة والبطاقة الشخصية</a>.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></p><h2 id="تأشيرة-الزيارة-العائلية" tabindex="-1">تأشيرة الزيارة العائلية <a class="header-anchor" href="#تأشيرة-الزيارة-العائلية" aria-label="Permalink to &quot;تأشيرة الزيارة العائلية&quot;">​</a></h2><p>تمنح الوزارة هذه التأشيرة لمدة شهر واحد، ويمكن تمديدها خمسة أشهر أخرى لأقارب الدرجة الأولى.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><h3 id="من-يمكنه-الاستضافة" tabindex="-1">من يمكنه الاستضافة <a class="header-anchor" href="#من-يمكنه-الاستضافة" aria-label="Permalink to &quot;من يمكنه الاستضافة&quot;">​</a></h3><ul><li>ألا تكون مهنتك من الفئة العمالية.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li>راتب شهري لا يقل عن 5,000 ريال قطري موثق بعقد عمل معتمد.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup><sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3]</a></sup></li><li>يجب أن يكون لدى الزائر تأمين صحي يغطي مدة الزيارة.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li></ul><h3 id="من-يمكنه-الزيارة" tabindex="-1">من يمكنه الزيارة <a class="header-anchor" href="#من-يمكنه-الزيارة" aria-label="Permalink to &quot;من يمكنه الزيارة&quot;">​</a></h3><ul><li>الدرجة الأولى: الأب والأم والزوجة والأبناء.<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2]</a></sup></li><li>الدرجة الثانية: الأخ والأخت والجد والجدة والأحفاد.<sup class="footnote-ref"><a href="#fn2" id="fnref2:6">[2]</a></sup></li><li>الدرجة الثالثة: أبناء الأخ أو الأخت، والأعمام والعمات والأخوال والخالات.<sup class="footnote-ref"><a href="#fn2" id="fnref2:7">[2]</a></sup></li></ul><p>يذكر إعلان 2023 أن سن الزائر غير محدد.<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3]</a></sup></p><h3 id="ما-تحتاجه-1" tabindex="-1">ما تحتاجه <a class="header-anchor" href="#ما-تحتاجه-1" aria-label="Permalink to &quot;ما تحتاجه&quot;">​</a></h3><ul><li>صورة جواز سفر الزائر سارية لمدة ستة أشهر على الأقل.<sup class="footnote-ref"><a href="#fn2" id="fnref2:8">[2]</a></sup></li><li>مستند يثبت صلة القرابة.<sup class="footnote-ref"><a href="#fn2" id="fnref2:9">[2]</a></sup></li><li>ما يثبت وجود سكن عائلي باسم المستضيف، معتمد من الجهات المختصة.<sup class="footnote-ref"><a href="#fn2" id="fnref2:10">[2]</a></sup></li></ul><h3 id="كيف-تقدم-الطلب-1" tabindex="-1">كيف تقدم الطلب <a class="header-anchor" href="#كيف-تقدم-الطلب-1" aria-label="Permalink to &quot;كيف تقدم الطلب&quot;">​</a></h3><p>قدّم الطلب عبر مطراش2 وارفع المستندات.<sup class="footnote-ref"><a href="#fn2" id="fnref2:11">[2]</a></sup></p><h2 id="تمديد-الزيارة-العائلية" tabindex="-1">تمديد الزيارة العائلية <a class="header-anchor" href="#تمديد-الزيارة-العائلية" aria-label="Permalink to &quot;تمديد الزيارة العائلية&quot;">​</a></h2><ul><li>للبقاء أكثر من شهر، أكمل الفحص الطبي قبل انتهاء المدة المسموح بها وقدّم طلب التمديد.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li><li>تتضمن صفحة خدمات التأشيرات في وزارة الداخلية خيار تمديد التأشيرة ودفع الغرامة.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li>إذا لم تُمدَّد التأشيرة قبل انتهائها، تُفرض غرامة عن كل يوم تأخير، والمبالغ مذكورة في صفحة الإرشادات.<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5]</a></sup></li></ul><h2 id="المواليد-الجدد" tabindex="-1">المواليد الجدد <a class="header-anchor" href="#المواليد-الجدد" aria-label="Permalink to &quot;المواليد الجدد&quot;">​</a></h2><p>توفر الوزارة تأشيرة مجانية للمواليد القادمين مع أمهاتهم إلى منفذ الدخول، لاستكمال إجراءات رخصة الإقامة. ويجب ألا يزيد عمر المولود على 6 أشهر.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><ul><li>يجب أن تكون رخصتا إقامة الأب والأم ساريتين، وأن تكون الزوجة على كفالة زوجها.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></li><li>أحضر شهادة ميلاد المولود الأصلية المصدقة وجواز سفره الساري.<sup class="footnote-ref"><a href="#fn7" id="fnref7:2">[7]</a></sup></li><li>تُنجز هذه الخدمة في منفذ الدخول لدى جوازات المنافذ.<sup class="footnote-ref"><a href="#fn7" id="fnref7:3">[7]</a></sup></li></ul><p>انظر أيضًا: <a href="./arriving-and-visas">الوصول والتأشيرات</a>، <a href="./residence-permit-and-qid">رخصة الإقامة والبطاقة الشخصية</a>، <a href="./metrash">مطراش</a>، <a href="./education">التعليم</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fnon-work%2Bentry%2Ffamily%2Bresidence%2Bvisa" target="_blank" rel="noreferrer">سمة الإقامة العائلية (Family Residence Visa)</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fnon-work%2Bvisit%2Fgggg" target="_blank" rel="noreferrer">الزيارة العائلية (Family Visit)</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:8" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:9" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:10" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:11" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-ar/sa-moinews/d978dff7-9fa3-4d39-a83f-cb3c3044dc52" target="_blank" rel="noreferrer">الاعلان عن تعديل بعض ضوابط وإجراءات استقدام عائلات المقيمين للإقامة أو الزيارة</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/departmentcommittees/ganationalborderexpatriateaffairs/!ut/p/z0/fY5BC4JAEEZ_jUeZzUPgUSKKggwMqr3E5I4y5c7aOpT9-yQ6d_sefDweWDiBFXxyi8pBsJv4bOeXXW6KWV6abbnIl9Mstodyvc-qIoMKNmD_XyYH3x4PW4CtgyiNCqdX7Tu-pjxhFNKUJDEDpo56jOpJtA7esypRYloSitih8yw8aPy2hUZ-jazva4iO4oDiaOxRI6MSNg1yHBLjWoX-vjp-AE6OsDQ!/" target="_blank" rel="noreferrer">شروط الموافقة على سمة الإقامة العائلية (Conditions for Family Residence Visa Approval)</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/47" target="_blank" rel="noreferrer">نصائح وإرشادات (Tips &amp; Guidelines)</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/visaservices" target="_blank" rel="noreferrer">خدمات التأشيرات (Visa Services)</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn7" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fnon-work%2Bentry%2Fvisa0125" target="_blank" rel="noreferrer">تأشيرة المواليد الجدد (Visa for New Born Babies)</a>. آخر تحقق: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref7:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref7:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',35)])])}const u=e(t,[["render",s]]);export{d as __pageData,u as default};
